    {
      "name": "TensorProduct.exists_multiset",
      "module_name": "Mathlib.LinearAlgebra.TensorProduct.Finiteness",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} {N : Type u_3} [inst : CommSemiring R] [inst_1 : AddCommMonoid M]\n  [inst_2 : AddCommMonoid N] [inst_3 : Module R M] [inst_4 : Module R N] (x : TensorProduct R M N),\n  ∃ S, x = (Multiset.map (fun i => i.1 ⊗ₜ[R] i.2) S).sum"
    },
    {
      "name": "TensorProduct.exists_finset",
      "module_name": "Mathlib.LinearAlgebra.TensorProduct.Finiteness",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} {N : Type u_3} [inst : CommSemiring R] [inst_1 : AddCommMonoid M]\n  [inst_2 : AddCommMonoid N] [inst_3 : Module R M] [inst_4 : Module R N] (x : TensorProduct R M N),\n  ∃ S, x = ∑ i ∈ S, i.1 ⊗ₜ[R] i.2"
    },
    {
      "name": "TensorProduct.exists_finsupp_left",
      "module_name": "Mathlib.LinearAlgebra.TensorProduct.Finiteness",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} {N : Type u_3} [inst : CommSemiring R] [inst_1 : AddCommMonoid M]\n  [inst_2 : AddCommMonoid N] [inst_3 : Module R M] [inst_4 : Module R N] (x : TensorProduct R M N),\n  ∃ S, x = S.sum fun m n => m ⊗ₜ[R] n"
    },
    {
      "name": "Algebra.TensorProduct.adjoin_tmul_eq_top",
      "module_name": "Mathlib.RingTheory.TensorProduct.Maps",
      "kind": "theorem",
      "type": "∀ (R : Type uR) (A : Type uA) (B : Type uB) [inst : CommSemiring R] [inst_1 : Semiring A] [inst_2 : Algebra R A]\n  [inst_3 : Semiring B] [inst_4 : Algebra R B], Algebra.adjoin R {t | ∃ a b, a ⊗ₜ[R] b = t} = ⊤"
    },
    {
      "name": "TensorProduct.span_tmul_eq_top",
      "module_name": "Mathlib.LinearAlgebra.TensorProduct.Basic",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) [inst : CommSemiring R] (M : Type u_7) (N : Type u_8) [inst_1 : AddCommMonoid M]\n  [inst_2 : AddCommMonoid N] [inst_3 : Module R M] [inst_4 : Module R N],\n  Submodule.span R {t | ∃ m n, m ⊗ₜ[R] n = t} = ⊤"
    }
  ]
